insert into public.fighters (id, display_name, team_id, gender, birth_year, city, region, country, joined_year, disciplines, fighting_style, bio, highlights) values
  ('dc986b96-be3f-5c26-914b-c1162aa0eb4b', 'Aldric Stone-test', '4842a217-7f85-509f-aa7e-cefa2bffbfab', 'male', 1995, 'Red Deer', 'AB', 'CA', 2021, array['5v5', '3v3', 'longsword']::text[], 'Longsword: pressure with the point, then close the line', 'Aldric Stone fights for Iron Wolves-test, a physical, melee-minded club in Red Deer. A heavy equipment technician who found the sport at a medieval festival. Joined in 2021. Enters 5v5, 3v3, Longsword. Has attended 10 NACL-test events (2023 to 2026) and fought 65 matches for a 42-23 record. A winning record overall. A tournament winner (11 gold). A regular podium finisher with 19 medals. One of the most active fighters in the league. Ranked 1 of 31 in Male 3v3 on career points.', array['Gold, Male 3v3, Rocky Mountain Rumble-test (2026)', 'Gold, Male 5v5, Medicine Hat Mayhem-test (2025)', 'Gold, Male 3v3, Medicine Hat Mayhem-test (2025)', 'Gold, Male 5v5, Prairie Crown Championship-test (2025)', 'Gold, Male 3v3, Prairie Crown Championship-test (2025)', 'Gold, Male 5v5, Edmonton Winter Melee-test (2024)', 'Career record 42-23 over 65 matches at 10 events', 'Career rank 1 of 31 in Male 3v3', 'Joined Iron Wolves-test in 2021']::text[]),
  ('b4b23592-ecfd-5625-92ec-4224c70404c2', 'Bram Holt-test', '4842a217-7f85-509f-aa7e-cefa2bffbfab', 'male', 1998, 'Sylvan Lake', 'AB', 'CA', 2022, array['sword_shield', '5v5', '3v3']::text[], 'Sword and shield: uses the rim to take space', 'Bram Holt fights for Iron Wolves-test, a physical, melee-minded club in Red Deer. A welder and fabricator who first repaired club equipment before he ever put it on. Joined in 2022. Enters Sword & Shield, 5v5, 3v3. Has attended 6 NACL-test events (2023 to 2026) and fought 38 matches for a 20-18 record. A winning record overall. A tournament winner (6 gold). A regular podium finisher with 11 medals. Results have dipped in recent seasons. Ranked 3 of 41 in Male 5v5 on career points.', array['Gold, Male 5v5, Queen City Combat Classic-test (2025)', 'Gold, Male 5v5, Medicine Hat Mayhem-test (2025)', 'Gold, Male 5v5, Edmonton Winter Melee-test (2024)', 'Gold, Male 3v3, Edmonton Winter Melee-test (2024)', 'Gold, Male 3v3, Okanagan Armored Open-test (2024)', 'Gold, Male 5v5, Calgary Iron Clash-test (2023)', 'Career record 20-18 over 38 matches at 6 events', 'Career rank 3 of 41 in Male 5v5', 'Joined Iron Wolves-test in 2022']::text[]),
  ('c88c4ad7-6508-52b3-a310-c9e2c4c6ba58', 'Cedric Vale-test', '4842a217-7f85-509f-aa7e-cefa2bffbfab', 'male', 1991, 'Red Deer', 'AB', 'CA', 2020, array['polearm', '5v5', '3v3']::text[], 'Polearm: controls the center, finishes with the butt', 'Cedric Vale fights for Iron Wolves-test, a physical, melee-minded club in Red Deer. A long-time recreational martial artist, balancing training with family and work. A veteran who joined in 2020. Enters Polearm, 5v5, 3v3. Has attended 3 NACL-test events (2025 to 2026) and fought 24 matches for a 11-13 record. A losing record so far. A tournament winner (4 gold). A regular podium finisher with 5 medals.', array['Gold, Male 5v5, Medicine Hat Mayhem-test (2025)', 'Gold, Male 3v3, Medicine Hat Mayhem-test (2025)', 'Gold, Male 5v5, Prairie Crown Championship-test (2025)', 'Gold, Male 3v3, Prairie Crown Championship-test (2025)', 'Bronze, Male 5v5, Pacific Steel Championship-test (2026)', 'Career record 11-13 over 24 matches at 3 events', 'Joined Iron Wolves-test in 2020']::text[]),
  ('7ba3fceb-e85e-5ed0-84a0-76915d6c6f83', 'Darius Flint-test', '4842a217-7f85-509f-aa7e-cefa2bffbfab', 'male', 2000, 'Lacombe', 'AB', 'CA', 2023, array['longsword']::text[], 'Longsword: pressure with the point, then close the line', 'Darius Flint fights for Iron Wolves-test, a physical, melee-minded club in Red Deer. Joined after a club demonstration; athletic, and still building his tournament experience. Joined in 2023. Enters Longsword. Has attended 7 NACL-test events (2023 to 2026) and fought 18 matches for a 8-10 record. A losing record so far. Has reached the podium 2 times. Results have improved season on season.', array['Silver, Male Longsword, Rocky Mountain Rumble-test (2026)', 'Bronze, Male Longsword, Medicine Hat Mayhem-test (2025)', 'Career record 8-10 over 18 matches at 7 events', 'Joined Iron Wolves-test in 2023']::text[]),
  ('cd820640-764f-55de-a68c-f916ff56fd18', 'Erik Thorn-test', '4842a217-7f85-509f-aa7e-cefa2bffbfab', 'male', 1993, 'Blackfalds', 'AB', 'CA', 2021, array['sword_shield', '5v5']::text[], 'Sword and shield: uses the rim to take space', 'Erik Thorn fights for Iron Wolves-test, a physical, melee-minded club in Red Deer. Works in industrial maintenance and brings the same patience to the field. Joined in 2021. Enters Sword & Shield, 5v5. Has attended 5 NACL-test events (2023 to 2025) and fought 12 matches for a 7-5 record. A winning record overall. A tournament winner (2 gold). A regular podium finisher with 4 medals.', array['Gold, Male 5v5, Edmonton Winter Melee-test (2024)', 'Gold, Male 5v5, Calgary Iron Clash-test (2023)', 'Silver, Male 5v5, Okanagan Armored Open-test (2024)', 'Silver, Male Sword & Shield, Calgary Iron Clash-test (2023)', 'Career record 7-5 over 12 matches at 5 events', 'Joined Iron Wolves-test in 2021']::text[]),
  ('bd195699-a4ba-5049-babf-d01f743911b5', 'Finn Mercer-test', '4842a217-7f85-509f-aa7e-cefa2bffbfab', 'male', 2002, 'Red Deer', 'AB', 'CA', 2024, array['polearm', '5v5', '3v3']::text[], 'Polearm: long reach and relentless tempo', 'Finn Mercer fights for Iron Wolves-test, a physical, melee-minded club in Red Deer. Volunteered at events before he ever competed, and only started fighting in late 2024. A newer competitor, joined in 2024. Enters Polearm, 5v5, 3v3. Has attended 3 NACL-test events (2024 to 2026) and fought 13 matches for a 6-7 record. A losing record so far. A tournament winner (2 gold). Has reached the podium 3 times.', array['Gold, Male 3v3, Rocky Mountain Rumble-test (2026)', 'Gold, Male 5v5, Medicine Hat Mayhem-test (2025)', 'Bronze, Male Polearm, Blackfalds Battle Bash-test (2024)', 'Career record 6-7 over 13 matches at 3 events', 'Joined Iron Wolves-test in 2024']::text[]),
  ('88af5e4f-d812-5e43-837b-5eb6dbb92226', 'Gunnar Reed-test', '4842a217-7f85-509f-aa7e-cefa2bffbfab', 'male', 1988, 'Innisfail', 'AB', 'CA', 2019, array['longsword', '3v3']::text[], 'Longsword: pressure with the point, then close the line', 'Gunnar Reed fights for Iron Wolves-test, a physical, melee-minded club in Red Deer. A long-time historical martial arts practitioner (his joining year is recorded as an assumption). A veteran who joined in 2019. Enters Longsword, 3v3. Has attended 7 NACL-test events (2023 to 2026) and fought 31 matches for a 18-13 record. A winning record overall. A tournament winner (5 gold). A regular podium finisher with 7 medals. Results have dipped in recent seasons. Ranked 4 of 25 in Male Longsword on career points.', array['Gold, Male 3v3, Medicine Hat Mayhem-test (2025)', 'Gold, Male 3v3, Prairie Crown Championship-test (2025)', 'Gold, Male 3v3, Edmonton Winter Melee-test (2024)', 'Gold, Male Longsword, Edmonton Winter Melee-test (2024)', 'Gold, Male 3v3, Okanagan Armored Open-test (2024)', 'Silver, Male Longsword, Prairie Crown Championship-test (2025)', 'Career record 18-13 over 31 matches at 7 events', 'Career rank 4 of 25 in Male Longsword', 'Joined Iron Wolves-test in 2019']::text[]),
  ('f5bf9cb2-e86b-5c61-bcc5-2d3febce1a61', 'Astrid Vale-test', '4842a217-7f85-509f-aa7e-cefa2bffbfab', 'female', 1996, 'Red Deer', 'AB', 'CA', 2021, array['longsword', '5v5', '3v3']::text[], 'Longsword: patient, technical and hard to bait', 'Astrid Vale fights for Iron Wolves-test, a physical, melee-minded club in Red Deer. Came to armored combat from historical fencing. Joined in 2021. Enters Longsword, 5v5, 3v3. Has attended 9 NACL-test events (2023 to 2026) and fought 29 matches for a 22-7 record. A winning record overall. A tournament winner (4 gold). A regular podium finisher with 9 medals. One of the most active fighters in the league. Ranked 1 of 19 in Female Longsword on career points.', array['Gold, Female Longsword, Prairie Siege-test (2025)', 'Gold, Female Longsword, Edmonton Winter Melee-test (2024)', 'Gold, Female Longsword, Okanagan Armored Open-test (2024)', 'Gold, Female Longsword, Calgary Iron Clash-test (2023)', 'Silver, Female Longsword, Grande Prairie Northern Clash-test (2026)', 'Silver, Female 5v5, Medicine Hat Mayhem-test (2025)', 'Career record 22-7 over 29 matches at 9 events', 'Career rank 1 of 19 in Female Longsword', 'Joined Iron Wolves-test in 2021']::text[]),
  ('7b4eb64c-041e-55c7-ade2-755393281205', 'Brynn Stone-test', '4842a217-7f85-509f-aa7e-cefa2bffbfab', 'female', 1999, 'Lacombe', 'AB', 'CA', 2022, array['sword_shield', '5v5']::text[], 'Melee specialist: strongest in the pack, around average in a duel', 'Brynn Stone fights for Iron Wolves-test, a physical, melee-minded club in Red Deer. Joined in 2022. Enters Sword & Shield, 5v5. Has attended 3 NACL-test events (2024 to 2026) and fought 8 matches for a 4-4 record. An even record overall. Has reached the podium 3 times.', array['Silver, Female 5v5, Pacific Steel Championship-test (2026)', 'Silver, Female Sword & Shield, Pacific Steel Championship-test (2026)', 'Silver, Female 5v5, Medicine Hat Mayhem-test (2025)', 'Career record 4-4 over 8 matches at 3 events', 'Joined Iron Wolves-test in 2022']::text[]),
  ('40795962-8124-5345-9a23-2700087b535f', 'Freya Holt-test', '4842a217-7f85-509f-aa7e-cefa2bffbfab', 'female', 1992, 'Olds', 'AB', 'CA', 2020, array['polearm']::text[], 'Polearm: long reach and relentless tempo', 'Freya Holt fights for Iron Wolves-test, a physical, melee-minded club in Red Deer. Picks her tournaments, and prefers the big ones. A veteran who joined in 2020. Enters Polearm. Has attended 3 NACL-test events (2023 to 2026) and fought 5 matches for a 1-4 record. Has yet to reach a podium.', array['Career record 1-4 over 5 matches at 3 events', 'Joined Iron Wolves-test in 2020']::text[]),
