  ('b9551194-d28a-50e3-9bfc-36c446fa8f54', 'Corbin Ash-test', '93d193e0-68eb-5bb6-a045-4b963f97ef22', 'male', 1989, 'Calgary', 'AB', 'CA', 2020, array['polearm', '5v5']::text[], 'Melee specialist: strongest in the pack, around average in a duel', 'Corbin Ash fights for Blackforge Knights-test, a club built on structured training in Calgary. A construction supervisor with little interest in duel rankings. A veteran who joined in 2020. Enters Polearm, 5v5. Has attended 6 NACL-test events (2023 to 2026) and fought 16 matches for a 8-8 record. An even record overall. A tournament winner (3 gold). A regular podium finisher with 4 medals.', array['Gold, Male 5v5, Rocky Mountain Rumble-test (2026)', 'Gold, Male 5v5, Prairie Siege-test (2025)', 'Gold, Male 5v5, Central Alberta Steel Open-test (2023)', 'Silver, Male 5v5, Saskatchewan Steel Cup-test (2023)', 'Career record 8-8 over 16 matches at 6 events', 'Joined Blackforge Knights-test in 2020']::text[]),
